import { runSecurityScannerTests } from "./bun-security-scanner-matrix-runner";

// CI Time maxes out at 3 minutes per test file. This test takes a little while
// but is useful enough justifying keeping it. This test file runs all the tests
// with an existing node modules folder. See
// ./bun-security-scanner-matrix-without-node-modules.test.ts for tests that run
// without
runSecurityScannerTests(import.meta.path, true);

import { expect, test } from "bun:test";
import { bunEnv, bunExe, tempDir } from "harness";

test("security scanner blocks bun update with fatal advisory", async () => {
  await using dir = tempDir("bun-update-security", {
    "package.json": JSON.stringify({
      name: "test-app",
      version: "1.0.0",
      dependencies: {
        "left-pad": "1.3.0", // There is a real update to 1.3.1
      },
    }),
    "scanner.ts": `
      export const scanner = {
        version: "1",
        scan: async ({ packages }) => {
          console.log("Security scanner received " + packages.length + " packages");
          if (packages.length === 0) return [];
          return [
            {
              package: packages[0].name,
              description: "Security warning for update test",
              level: "fatal",
              url: "https://example.com/advisory",
            },
          ];
        },
      };
    `,
  });

  // First install without scanner
  await using installProc = Bun.spawn({
    cmd: [bunExe(), "install"],
    env: bunEnv,
    cwd: dir,
    stdout: "pipe",
    stderr: "pipe",
  });

  await installProc.stdout.text();
  await installProc.stderr.text();
  const installCode = await installProc.exited;
  expect(installCode).toBe(0);

  // Now add scanner for update
  await Bun.write(Bun.pathToFileURL(`${dir}/bunfig.toml`), `[install.security]\nscanner = "./scanner.ts"`);

  await using updateProc = Bun.spawn({
    cmd: [bunExe(), "update", "left-pad", "--latest"],
    env: bunEnv,
    cwd: dir,
    stdout: "pipe",
    stderr: "pipe",
    stdin: "pipe",
  });

  const [out, exitCode] = await Promise.all([updateProc.stdout.text(), updateProc.exited]);

  expect(out).toContain("Security scanner received");
  expect(out).toContain("FATAL: left-pad");
  expect(out).toContain("Security warning for update test");
  expect(out).toContain("Installation aborted due to fatal security advisories");
  expect(exitCode).toBe(1);
});

test("security scanner does not run on bun update when not configured", async () => {
  await using dir = tempDir("bun-update-no-security", {
    "package.json": JSON.stringify({
      name: "test-app",
      version: "1.0.0",
      dependencies: {
        "left-pad": "1.3.0",
      },
    }),
  });

  await using installProc = Bun.spawn({
    cmd: [bunExe(), "install"],
    env: bunEnv,
    cwd: dir,
    stdout: "pipe",
    stderr: "pipe",
  });

  const installCode = await installProc.exited;
  expect(installCode).toBe(0);

  await using updateProc = Bun.spawn({
    cmd: [bunExe(), "update", "left-pad", "--latest"],
    env: bunEnv,
    cwd: dir,
    stdout: "pipe",
    stderr: "pipe",
  });

  const [out, err, exitCode] = await Promise.all([
    updateProc.stdout.text(),
    updateProc.stderr.text(),
    updateProc.exited,
  ]);

  const combined = out + err;
  expect(combined).not.toContain("Security scanner");
  expect(combined).not.toContain("FATAL:");
  expect(combined).not.toContain("WARN:");

  expect(exitCode).toBe(0);
});

import { file } from "bun";
import { afterAll, beforeAll, expect, test } from "bun:test";
import { bunEnv, bunExe, normalizeBunSnapshot } from "harness";
import { join } from "node:path";
import {
  createTestContext,
  destroyTestContext,
  dummyAfterAll,
  dummyBeforeAll,
  dummyRegistryForContext,
  setContextHandler,
  type TestContext,
} from "./dummy.registry.js";

beforeAll(dummyBeforeAll);
afterAll(dummyAfterAll);

// Reports what it was asked to scan, then flags all of it as fatal: an update
// that consults this scanner cannot succeed, so a successful update proves the
// scanner was never run.
const scannerSource = `
  export const scanner = {
    version: "1",
    scan: async ({ packages }) => {
      console.log("scanner received: " + packages.map(pkg => pkg.name + "@" + pkg.version).join(", "));
      return packages.map(pkg => ({
        package: pkg.name,
        description: "Fatal security issue detected",
        level: "fatal",
        url: "https://example.com/critical",
      }));
    },
  };
`;

// The three things `bun update moo` changes: the package.json range, the
// lockfile resolution and the package on disk. Every test starts from this state.
const installedState = { range: ">=0.1.0", locked: "moo@0.1.0", installed: "0.1.0" };

async function mooState(ctx: TestContext) {
  const [packageJson, lockfile, installed] = await Promise.all([
    file(join(ctx.package_dir, "package.json")).json(),
    file(join(ctx.package_dir, "bun.lock")).text(),
    file(join(ctx.package_dir, "node_modules/moo/package.json")).json(),
  ]);
  return {
    range: packageJson.dependencies.moo,
    locked: (Bun.JSONC.parse(lockfile) as { packages: Record<string, [string, ...unknown[]]> }).packages.moo[0],
    installed: installed.version,
  };
}

// Writes out what `bun install` leaves behind for `installedState` (the
// lockfile and node_modules entry are what it writes against this registry),
// which saves spawning an install per test. The registry has since published
// 0.2.0. The scanner file always exists; only bunfig.toml decides whether bun
// uses it.
async function projectWithMooInstalled({ scanner }: { scanner: boolean }) {
  const ctx = await createTestContext();
  const urls: string[] = [];
  setContextHandler(ctx, dummyRegistryForContext(ctx, urls, { "0.1.0": {}, "0.2.0": {} }));

  const files = {
    "bunfig.toml": Bun.TOML.stringify({
      install: {
        // Without this, manifests and tarballs come from the machine-wide cache
        // and the requests asserted below never reach the registry.
        cache: false,
        registry: ctx.registry_url,
        security: scanner ? { scanner: "./scanner.ts" } : undefined,
      },
    })!,
    "scanner.ts": scannerSource,
    "package.json": JSON.stringify({ name: "my-app", version: "1.0.0", dependencies: { moo: installedState.range } }),
    "bun.lock": JSON.stringify({
      lockfileVersion: 1,
      configVersion: 1,
      workspaces: { "": { name: "my-app", dependencies: { moo: installedState.range } } },
      packages: { moo: [installedState.locked, `${ctx.registry_url}moo-${installedState.installed}.tgz`, {}, ""] },
    }),
    "node_modules/moo/package.json": JSON.stringify({ name: "moo", version: installedState.installed }),
  };
  await Promise.all(Object.entries(files).map(([name, contents]) => Bun.write(join(ctx.package_dir, name), contents)));
  return { ctx, urls };
}

async function updateMoo(ctx: TestContext) {
  await using proc = Bun.spawn({
    cmd: [bunExe(), "update", "moo"],
    cwd: ctx.package_dir,
    env: bunEnv,
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited]);
  return {
    stdout: normalizeBunSnapshot(stdout),
    // Only printed when the scanner takes over a second, i.e. on slow debug builds.
    stderr: normalizeBunSnapshot(stderr.replace(/^\[\.\/scanner\.ts\] Scanning 1 package took \d+ms\r?\n/m, "")),
    exitCode,
  };
}

test.concurrent("security scanner blocks bun update on fatal advisory", async () => {
  const { ctx, urls } = await projectWithMooInstalled({ scanner: true });
  try {
    const { stdout, stderr, exitCode } = await updateMoo(ctx);
    expect(stdout).toMatchInlineSnapshot(`
      "bun update <version> (<revision>)
      scanner received: moo@0.2.0

        FATAL: moo
          via my-app › moo
          Fatal security issue detected
          https://example.com/critical

      1 advisory (1 fatal)
      Installation aborted due to fatal security advisories"
    `);
    expect(stderr).toMatchInlineSnapshot(`
      "Resolving dependencies
      Resolved, downloaded and extracted [2]"
    `);
    expect(exitCode).toBe(1);

    // The advisory stopped the update right after resolution: the 0.2.0
    // tarball was never downloaded and nothing on disk moved off 0.1.0.
    expect(urls).toEqual([`${ctx.registry_url}moo`]);
    expect(await mooState(ctx)).toEqual(installedState);
  } finally {
    destroyTestContext(ctx);
  }
});

test.concurrent("security scanner does not run on bun update when not configured", async () => {
  const { ctx, urls } = await projectWithMooInstalled({ scanner: false });
  try {
    const { stdout, stderr, exitCode } = await updateMoo(ctx);
    expect(stdout).toMatchInlineSnapshot(`
      "bun update <version> (<revision>)

      ^ moo 0.1.0 -> 0.2.0

      1 package installed"
    `);
    expect(stderr).toMatchInlineSnapshot(`
      "Resolving dependencies
      Resolved, downloaded and extracted [4]
      Saved lockfile"
    `);
    expect(exitCode).toBe(0);

    expect(urls).toEqual([`${ctx.registry_url}moo`, `${ctx.registry_url}moo-0.2.0.tgz`]);
    // `>=0.1.0` still covers 0.2.0, so the literal is kept.
    expect(await mooState(ctx)).toEqual({ range: ">=0.1.0", locked: "moo@0.2.0", installed: "0.2.0" });
  } finally {
    destroyTestContext(ctx);
  }
});

import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { bunEnv, bunExe, tempDir } from "harness";
import { join } from "node:path";
import { startRegistry, stopRegistry } from "./simple-dummy-registry";

let registryUrl: string;

beforeAll(async () => {
  registryUrl = await startRegistry(false);
});

afterAll(() => {
  stopRegistry();
});

function bunfig({ scanner }: { scanner: boolean }) {
  let text = `[install]
cache = false
registry = "${registryUrl}/"
`;
  if (scanner) {
    text += `
[install.security]
scanner = "./scanner.js"
`;
  }
  return text;
}

async function primeInstall(dir: string) {
  await Bun.write(join(dir, "bunfig.toml"), bunfig({ scanner: false }));
  await Bun.$`${bunExe()} install`.cwd(dir).env(bunEnv).quiet();
  await Bun.write(join(dir, "bunfig.toml"), bunfig({ scanner: true }));
}

// Each test spawns two debug-build bun processes (install + update) and they run
// concurrently, so per-test wall time is higher under CPU contention even though
// total wall time drops. Matches bun-install-security-provider.test.ts.
const timeout = 30_000;

describe.concurrent("bun update security scanning", () => {
  test(
    "bun update without arguments scans all packages",
    async () => {
      await using dir = tempDir("update-scan-all", {
        "package.json": JSON.stringify({
          name: "test-app",
          dependencies: {
            "left-pad": "1.3.0",
            "is-even": "1.0.0",
          },
        }),
        "scanner.js": `
let callCount = 0;
module.exports = {
  scanner: {
    version: "1",
    scan: async function(payload) {
      callCount++;
      const packageNames = payload.packages.map(p => p.name).sort();
      console.error("SCAN_CALL_" + callCount + ":", JSON.stringify(packageNames));
      const results = [];
      for (const pkg of payload.packages) {
        if (pkg.name === "left-pad") {
          results.push({
            package: "left-pad",
            level: "warn",
            description: "Test warning in left-pad",
            url: "https://example.com/left-pad-advisory"
          });
        }
        if (pkg.name === "is-even") {
          results.push({
            package: "is-even",
            level: "warn",
            description: "Test warning in is-even",
            url: "https://example.com/is-even-advisory"
          });
        }
      }
      return results;
    }
  }
};
`,
      });

      await primeInstall(String(dir));

      await using proc = Bun.spawn({
        cmd: [bunExe(), "update"],
        cwd: String(dir),
        stdout: "pipe",
        stderr: "pipe",
        env: bunEnv,
      });

      const [stdout, stderr, exitCode] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited]);

      // The scanner ran once and received every package in the graph.
      expect(stderr).toContain(`SCAN_CALL_1: ["is-even","is-odd","left-pad"]`);
      expect(stderr).not.toContain("SCAN_CALL_2:");

      expect(stdout).toContain("WARNING: left-pad");
      expect(stdout).toContain("Test warning in left-pad");
      expect(stdout).toContain("WARNING: is-even");
      expect(stdout).toContain("Test warning in is-even");
      expect(stdout).toMatch(/2 advisories \(.*2 warning.*\)/);

      // Warnings require confirmation; with no TTY the update is cancelled.
      expect(stdout).toContain("Installation cancelled");
      expect(exitCode).toBe(1);
    },
    timeout,
  );

  test(
    "bun update with specific packages only scans those packages",
    async () => {
      await using dir = tempDir("update-scan-specific", {
        "package.json": JSON.stringify({
          name: "test-app",
          dependencies: {
            "left-pad": "1.3.0",
            "is-even": "1.0.0",
          },
        }),
        "scanner.js": `
module.exports = {
  scanner: {
    version: "1",
    scan: async function(payload) {
      const packageNames = payload.packages.map(p => p.name).sort();
      console.error("SCANNED_PACKAGES:", JSON.stringify(packageNames));
      const results = [];
      for (const pkg of payload.packages) {
        if (pkg.name === "left-pad") {
          results.push({
            package: "left-pad",
            level: "warn",
            description: "Test warning"
          });
        }
        if (pkg.name === "is-even") {
          results.push({
            package: "is-even",
            level: "fatal",
            description: "Should not see this"
          });
        }
      }
      return results;
    }
  }
};
`,
      });

      await primeInstall(String(dir));

      await using proc = Bun.spawn({
        cmd: [bunExe(), "update", "left-pad"],
        cwd: String(dir),
        stdout: "pipe",
        stderr: "pipe",
        env: bunEnv,
      });

      const [stdout, stderr, exitCode] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited]);

      // Only the requested package is sent to the scanner.
      expect(stderr).toContain(`SCANNED_PACKAGES: ["left-pad"]`);
      expect(stdout).toContain("WARNING: left-pad");
      expect(stdout).toContain("Test warning");

      // is-even was not part of this update, so its fatal advisory must not surface.
      expect(stdout).not.toContain("FATAL: is-even");
      expect(stdout).not.toContain("Should not see this");

      expect(exitCode).toBe(1);
    },
    timeout,
  );

  test(
    "bun update respects security scanner configuration",
    async () => {
      await using dir = tempDir("update-no-scanner", {
        "package.json": JSON.stringify({
          name: "test-app",
          dependencies: {
            "left-pad": "1.3.0",
          },
        }),
      });

      await Bun.write(join(String(dir), "bunfig.toml"), bunfig({ scanner: false }));
      await Bun.$`${bunExe()} install`.cwd(String(dir)).env(bunEnv).quiet();

      await using proc = Bun.spawn({
        cmd: [bunExe(), "update"],
        cwd: String(dir),
        stdout: "pipe",
        stderr: "pipe",
        env: bunEnv,
      });

      const [stdout, stderr, exitCode] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited]);

      expect(stdout).not.toContain("WARNING:");
      expect(stdout).not.toContain("FATAL:");
      expect(stderr).not.toContain("Scanning");
      expect(exitCode).toBe(0);
    },
    timeout,
  );

  test(
    "bun update aborts on fatal vulnerabilities",
    async () => {
      await using dir = tempDir("update-abort-fatal", {
        "package.json": JSON.stringify({
          name: "test-app",
          dependencies: {
            "left-pad": "1.3.0",
          },
        }),
        "scanner.js": `
module.exports = {
  scanner: {
    version: "1",
    scan: async function(payload) {
      return [{
        package: "left-pad",
        level: "fatal",
        description: "Critical security vulnerability",
        url: "https://example.com/CVE-1234"
      }];
    }
  }
};
`,
      });

      await primeInstall(String(dir));

      await using proc = Bun.spawn({
        cmd: [bunExe(), "update"],
        cwd: String(dir),
        stdout: "pipe",
        stderr: "pipe",
        env: bunEnv,
      });

      const [stdout, stderr, exitCode] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited]);

      expect(stdout).toContain("FATAL: left-pad");
      expect(stdout).toContain("Critical security vulnerability");
      expect(stdout).toContain("https://example.com/CVE-1234");
      expect(stdout).toContain("Installation aborted due to fatal security advisories");
      expect(exitCode).toBe(1);
    },
    timeout,
  );

  test.todo("bun update prompts for warnings when TTY available - requires TTY for interactive prompt");

  test(
    "bun update shows dependency paths correctly",
    async () => {
      await using dir = tempDir("update-dep-paths", {
        "package.json": JSON.stringify({
          name: "my-app",
          dependencies: {
            "is-even": "1.0.0",
          },
        }),
        "scanner.js": `
module.exports = {
  scanner: {
    version: "1",
    scan: async function(payload) {
      const results = [];
      for (const pkg of payload.packages) {
        if (pkg.name === "is-odd") {
          results.push({
            package: "is-odd",
            level: "warn",
            description: "Transitive vulnerability"
          });
        }
      }
      return results;
    }
  }
};
`,
      });

      await primeInstall(String(dir));

      await using proc = Bun.spawn({
        cmd: [bunExe(), "update"],
        cwd: String(dir),
        stdout: "pipe",
        stderr: "pipe",
        env: bunEnv,
      });

      const [stdout, stderr, exitCode] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited]);

      expect(stdout).toContain("WARNING: is-odd");
      expect(stdout).toContain("Transitive vulnerability");
      expect(stdout).toContain("via my-app › is-even › is-odd");
      expect(exitCode).toBe(1);
    },
    timeout,
  );
});

import { file } from "bun";
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { bunEnv, bunExe } from "harness";
import { basename, join } from "node:path";
import {
  createTestContext,
  destroyTestContext,
  dummyAfterAll,
  dummyBeforeAll,
  setContextHandler,
  type TestContext,
} from "./dummy.registry.js";

beforeAll(dummyBeforeAll);
afterAll(dummyAfterAll);

type PackageMap = Record<string, Record<string, { dependencies?: Record<string, string> }>>;

// Serves per-package version metadata from a local registry (tarballs live next
// to this file), so these tests never touch the public npm registry.
function makeRegistryHandler(ctx: TestContext, packages: PackageMap) {
  return async (request: Request) => {
    const url = request.url.replaceAll("%2f", "/");
    if (url.endsWith(".tgz")) {
      return new Response(file(join(import.meta.dir, basename(url).toLowerCase())));
    }
    const name = new URL(url).pathname.replace(`/${ctx.id}/`, "").replace(/^\//, "");
    const versionInfo = packages[name];
    if (!versionInfo) return new Response("not found", { status: 404 });
    const versions: Record<string, unknown> = {};
    let latest = "";
    for (const version of Object.keys(versionInfo)) {
      latest = version;
      versions[version] = {
        name,
        version,
        dist: { tarball: `${ctx.registry_url}${name}-${version}.tgz` },
        dependencies: versionInfo[version].dependencies ?? {},
      };
    }
    return new Response(JSON.stringify({ name, versions, "dist-tags": { latest } }));
  };
}

async function setup(options: {
  packages: PackageMap;
  dependencies: Record<string, string>;
  scanner: string;
  scannerEnabled?: boolean;
}) {
  const ctx = await createTestContext();
  setContextHandler(ctx, makeRegistryHandler(ctx, options.packages));
  const dir = ctx.package_dir;

  const writeBunfig = (withScanner: boolean) =>
    Bun.write(
      join(dir, "bunfig.toml"),
      `[install]
cache = false
registry = "${ctx.registry_url}"
saveTextLockfile = false
${withScanner ? `\n[install.security]\nscanner = "./scanner.js"\n` : ""}`,
    );

  await Promise.all([
    Bun.write(join(dir, "package.json"), JSON.stringify({ name: "test-app", dependencies: options.dependencies })),
    Bun.write(join(dir, "scanner.js"), options.scanner),
    writeBunfig(options.scannerEnabled ?? false),
  ]);

  return { ctx, dir, writeBunfig };
}

async function run(dir: string, args: string[]) {
  await using proc = Bun.spawn({
    cmd: [bunExe(), ...args],
    cwd: dir,
    env: bunEnv,
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited]);
  return { stdout, stderr, exitCode };
}

// Concurrent spawns contend for CPU on slow debug/ASAN lanes, so per-test wall
// time is higher than sequential even though total wall time drops. 30s matches
// the sibling security-scanner tests.
const timeout = 30_000;

describe.concurrent("bun update security edge cases", () => {
  test(
    "bun update detects vulnerability in updated version that was safe before",
    async () => {
      const { ctx, dir, writeBunfig } = await setup({
        packages: { baz: { "0.0.3": {}, "0.0.5": {} } },
        dependencies: { baz: "0.0.3" },
        scanner: `
module.exports = {
  scanner: {
    version: "1",
    scan: async function (payload) {
      const results = [];
      for (const pkg of payload.packages) {
        if (pkg.name === "baz" && pkg.version === "0.0.5") {
          results.push({
            package: "baz",
            level: "fatal",
            description: "CVE-2024-XXXX: Prototype pollution in baz 0.0.5",
            url: "https://example.com/CVE-2024-XXXX",
          });
        }
      }
      return results;
    },
  },
};`,
      });
      try {
        const install = await run(dir, ["install"]);
        expect(install.stderr).toContain("Saved lockfile");
        expect(install.exitCode).toBe(0);

        await writeBunfig(true);
        await Bun.write(
          join(dir, "package.json"),
          JSON.stringify({ name: "test-app", dependencies: { baz: ">=0.0.3" } }),
        );

        const { stdout, exitCode } = await run(dir, ["update"]);
        expect(stdout).toContain("FATAL: baz");
        expect(stdout).toContain("CVE-2024-XXXX: Prototype pollution in baz 0.0.5");
        expect(stdout).toContain("Installation aborted due to fatal security advisories");
        expect(exitCode).toBe(1);
      } finally {
        destroyTestContext(ctx);
      }
    },
    timeout,
  );

  test(
    "bun update <pkg> detects vulnerability in the specific updated package",
    async () => {
      const { ctx, dir, writeBunfig } = await setup({
        packages: { baz: { "0.0.3": {}, "0.0.5": {} } },
        dependencies: { baz: "0.0.3" },
        scanner: `
module.exports = {
  scanner: {
    version: "1",
    scan: async function (payload) {
      const results = [];
      for (const pkg of payload.packages) {
        if (pkg.name === "baz" && Bun.semver.satisfies(pkg.version, ">=0.0.5")) {
          results.push({
            package: "baz",
            level: "fatal",
            description: "CVE-2023-45857: baz vulnerable to SSRF in >=0.0.5",
            url: "https://nvd.nist.gov/vuln/detail/CVE-2023-45857",
          });
        }
      }
      return results;
    },
  },
};`,
      });
      try {
        const install = await run(dir, ["install"]);
        expect(install.stderr).toContain("Saved lockfile");
        expect(install.exitCode).toBe(0);

        await writeBunfig(true);

        const { stdout, exitCode } = await run(dir, ["update", "baz", "--latest"]);
        expect(stdout).toContain("FATAL: baz");
