          },
        },
        null,
        2,
      ),
      "packages/lib1/package.json": JSON.stringify(
        {
          name: "lib1",
          dependencies: {
            "is-odd": "1.0.0",
          },
        },
        null,
        2,
      ),
      "scanner.js": `export const scanner = {
  version: "1",
  scan: async function(payload) {
